UICelebrationTrophyGroup=function(game,winnerCelebrationSound,tieSound){Phaser.Group.call(this,game,null);this.winnerCelebrationSound=winnerCelebrationSound;this.tieSound=tieSound;this.header=this.addChild(new Phaser.Text(game,0,UIConstants.CELEBRATION_HEADER_Y,'',{font:UIConstants.CELEBRATION_HEADER_FONT_SIZE+"px TankTrouble",fontWeight:"bold",fill:"#000000",stroke:"#ffffff",strokeThickness:UIConstants.CELEBRATION_HEADER_STROKE_WIDTH}));this.header.anchor.setTo(0.5,0.5);this.trophySprite=this.addChild(new Phaser.Image(this.game,0,0,'celebration','trophy'));this.trophySprite.anchor.setTo(0.5,0.5);this.tankIconSprite=this.addChild(new UITankIconImage(this.game,false,UIConstants.TANK_ICON_SIZES.LARGE));this.tankIconSprite.anchor.setTo(0.5,0.5);this.tieSprite=this.addChild(new Phaser.Image(this.game,0,UIConstants.CELEBRATION_TIE_Y,'celebration','poop'));this.tieSprite.anchor.setTo(0.5,0.5);this.trophyBaseFragmentGroup=this.game.add.group(this);for(var i=0;i<UIConstants.TROPHY_BASE_FRAGMENT_POOL_SIZE;++i){this.trophyBaseFragmentGroup.add(new UITrophyExplosionFragmentSprite(game,'trophyBaseFragment',true,3));}this.trophyFragmentGroup=this.game.add.group(this);for(var i=0;i<UIConstants.TROPHY_FRAGMENT_POOL_SIZE;++i){this.trophyFragmentGroup.add(new UITrophyExplosionFragmentSprite(game,'trophyFragment',true,5));}this.trophyLeftHandleSprite=this.addChild(new UITrophyExplosionFragmentSprite(game,'trophyLeftHandle',false));this.trophyRightHandleSprite=this.addChild(new UITrophyExplosionFragmentSprite(game,'trophyRightHandle',false));this.confettiEmitter=this.addChild(new UIConfettiEmitter(game));this.explosionEmitter=this.addChild(new UITrophyExplosionEmitter(game));this.floorBody=new Phaser.Physics.P2.Body(game,null,0.0,0.0);this.floorBody.static=true;this.floorBody.addPlane(0.0,UIConstants.TROPHY_EXPLOSION_FLOOR_Y,0.0);this.floorBody.setMaterial(UIUtils.gameFloorMaterial);this.floorBody.setCollisionGroup(UIUtils.gameFloorCollisionGroup);this.floorBody.collides([UIUtils.trophyFragmentCollisionGroup]);this.exists=false;this.visible=false;this.header.kill();this.trophySprite.kill();this.tankIconSprite.kill();this.tieSprite.kill();this.victoryAward=null;this.timeAlive=0.0;this.exploded=false;this.handedOutPrizes=false;this.ended=false;this.log=Log.create('UICelebrationTrophyGroup');};UICelebrationTrophyGroup.prototype=Object.create(Phaser.Group.prototype);UICelebrationTrophyGroup.prototype.constructor=UICelebrationTrophyGroup;UICelebrationTrophyGroup.prototype.update=function(){if(!this.exists){return;}this.timeAlive+=this.game.time.delta/1000;if(!this.exploded){if(this.timeAlive>=UIConstants.CELEBRATION_TROPHY_LIFETIME){this._explode();}}if(!this.handedOutPrizes){if(this.timeAlive>=UIConstants.CELEBRATION_PRIZE_HANDOUT_TIME){var gameBounds=this.game.scale.bounds;var position=this.tankIconSprite.toGlobal(new Phaser.Point(0,0));Phaser.Point.divide(position,this.game.scale.scaleFactor,position);var pagePosition={x:gameBounds.x+position.x,y:gameBounds.y+position.y};for(var i=0;i<this.victoryAward.getPlayerIds().length;++i){var playerId=this.victoryAward.getPlayerIds()[i];GameManager.sendVictoryGoldToTank(playerId,this.victoryAward.getGoldAmountPerWinner(),pagePosition);GameManager.showXPChange(this.victoryAward.getExperiencePerWinner(),UIPlayerPanel.getLocalTankIconPosition(playerId),1200);}UIPlayerPanel.showRankChanges(this.victoryAward.getRankChanges());this.handedOutPrizes=true;}}if(!this.ended){if(this.timeAlive>=UIConstants.CELEBRATION_TANK_LIFETIME){if(this.victoryAward.getPlayerIds().length>0){this.game.add.tween(this.header.scale).to({x:0.0,y:0.0},UIConstants.ELEMENT_GLIDE_OUT_TIME,Phaser.Easing.Linear.None,true);this.tankIconSprite.remove();this.ended=true;}}}Phaser.Group.prototype.update.call(this);};UICelebrationTrophyGroup.prototype.postUpdate=function(){if(!this.exists){return;}Phaser.Group.prototype.postUpdate.call(this);};UICelebrationTrophyGroup.prototype.spawn=function(x,y,modeName,victoryAward){this.exists=true;this.visible=true;this.x=x;this.y=y;this.victoryAward=victoryAward;this.timeAlive=0.0;this.exploded=false;this.handedOutPrizes=false;this.ended=false;this.game.physics.p2.addBody(this.floorBody);this.game.physics.p2.gravity.y=UIConstants.TROPHY_FRAGMENT_GRAVITY;this.header.revive();this.header.setText(modeName+' winner is..');this.header.scale.set(0.0,0.0);this.game.add.tween(this.header.scale).to({x:1.0,y:1.0},UIConstants.ELEMENT_POP_IN_TIME,Phaser.Easing.Back.Out,true);this.trophySprite.revive();this.trophySprite.scale.set(0.0,0.0);this.tankIconSprite.retire();this.game.add.tween(this.trophySprite.scale).to({x:1.0,y:1.0},UIConstants.ELEMENT_POP_IN_TIME,Phaser.Easing.Back.Out,true);};UICelebrationTrophyGroup.prototype._explode=function(){this.exploded=true;this.game.add.tween(this.trophySprite.scale).to({x:1.2,y:1.2},UIConstants.ELEMENT_GLIDE_OUT_TIME,Phaser.Easing.Back.In,true).onComplete.add(function(){this.trophySprite.kill();for(var i=0;i<UIConstants.TROPHY_BASE_FRAGMENT_POOL_SIZE;++i){var fragment=this.trophyBaseFragmentGroup.getFirstExists(false);if(fragment){fragment.spawn(0,UIConstants.TROPHY_EXPLOSION_Y+UIConstants.TROPHY_BASE_FRAGMENT_EXPLOSION_OFFSET,this.trophySprite.width*0.75,this.trophySprite.height*0.25);}else{this.log.error("Could not create trophy fragment sprite. No sprite available.");}}for(var i=0;i<UIConstants.TROPHY_FRAGMENT_POOL_SIZE;++i){var fragment=this.trophyFragmentGroup.getFirstExists(false);if(fragment){fragment.spawn(0,UIConstants.TROPHY_EXPLOSION_Y,this.trophySprite.width*0.75,this.trophySprite.height*0.75);}else{this.log.error("Could not create trophy fragment sprite. No sprite available.");}}this.trophyLeftHandleSprite.spawn(-this.trophySprite.width*0.355,-this.trophySprite.height*0.295,0,0,false);this.trophyRightHandleSprite.spawn(this.trophySprite.width*0.355,-this.trophySprite.height*0.295,0,0,false);this.confettiEmitter.spawn(0,0);this.explosionEmitter.spawn(0,UIConstants.TROPHY_EXPLOSION_Y);},this);this.winnerCelebrationSound.play();if(this.victoryAward.getPlayerIds().length>0){var self=this;Backend.getInstance().getPlayerDetails(function(result){if(typeof(result)=="object"){var username=Utils.maskUnapprovedUsername(result);self.header.setText(username);self.game.add.tween(self.header.scale).to({x:1.4,y:1.4},UIConstants.ELEMENT_POP_IN_TIME,Phaser.Easing.Back.Out,true);}else{self.header.setText("Scrapped");}},null,null,this.victoryAward.getPlayerIds()[0],Caches.getPlayerDetailsCache());this.tankIconSprite.spawn(0,0,this.victoryAward.getPlayerIds()[0],false,true);}else{this.tieSprite.revive();this.tieSprite.scale.set(0.0,0.0);this.game.add.tween(this.tieSprite.scale).to({x:1.0,y:1.0},UIConstants.ELEMENT_POP_IN_TIME,Phaser.Easing.Back.Out,true,2000).onStart.add(function(){this.tieSound.play();},this);this.header.setText("Nobody!");}};UICelebrationTrophyGroup.prototype.retire=function(){this.confettiEmitter.retire();this.explosionEmitter.retire();this.game.physics.p2.removeBody(this.floorBody);this.game.physics.p2.gravity.y=0;this.trophyBaseFragmentGroup.callAll('retire');this.trophyFragmentGroup.callAll('retire');this.trophyLeftHandleSprite.retire();this.trophyRightHandleSprite.retire();this.header.kill();this.trophySprite.kill();this.tankIconSprite.kill();this.tieSprite.kill();this.exists=false;this.visible=false;};